inputs = ['cbu', 'hwzudu', 'ihyeuk', 'dcx', 'wxdux']
outputs = ['cijgu', 'hwzudu', 'ihyeuk', 'dchzu', 'whzudzh']

# Analyze the changes
changes = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changes.append((i, inp, outp))
        print(f"Change {i}: '{inp}' -> '{outp}'")

print("\nAnalyzing specific changes:")
for idx, inp, outp in changes:
    print(f"  Position analysis for '{inp}' -> '{outp}':")
    # Find differences character by character
    min_len = min(len(inp), len(outp))
    for j in range(min_len):
        if inp[j] != outp[j]:
            print(f"    Position {j}: '{inp[j]}' -> '{outp[j]}'")
    if len(inp) != len(outp):
        print(f"    Length difference: {len(inp)} -> {len(outp)}")

